export function stronglyConnectedComponents(n, edges) {
  const forward = Array.from({ length: n }, () => []);
  const reverse = Array.from({ length: n }, () => []);
  for (const [from, to] of edges) {
    forward[from].push(to);
    reverse[to].push(from);
  }
  const seen = Array(n).fill(false);
  const order = [];
  function finish(vertex) {
    seen[vertex] = true;
    for (const next of forward[vertex]) if (!seen[next]) finish(next);
    order.push(vertex);
  }
  for (let vertex = 0; vertex < n; vertex++) if (!seen[vertex]) finish(vertex);
  seen.fill(false);
  const components = [];
  function collect(vertex, component) {
    seen[vertex] = true;
    component.push(vertex);
    for (const next of reverse[vertex]) if (!seen[next]) collect(next, component);
  }
  for (let index = order.length - 1; index >= 0; index--) {
    const vertex = order[index];
    if (seen[vertex]) continue;
    const component = [];
    collect(vertex, component);
    component.sort((a, b) => a - b);
    components.push(component);
  }
  return components.sort((a, b) => a[0] - b[0]);
}

